-- +goose Up

INSERT INTO scenarios (role, order_index, title, situation, question, options, correct_option, explanation, red_flags) VALUES
('seller', 1,
 'Ссылка на получение оплаты',
 'Вы продаёте смартфон за 45 000 ₽. Через час после публикации пишет покупатель: «Здравствуйте! Беру, оформил доставку через сервис. Деньги уже зарезервированы, вам осталось получить их по ссылке: avito-dostavka-pay.example/get — там подтвердите карту для зачисления».',
 'Что вы сделаете?',
 '[
   {"text": "Перейти по ссылке и ввести данные карты", "verdict": "dangerous", "outcome": "Страница — копия Авито. Введённые номер карты, срок и код превращаются в полный доступ к счёту: деньги списываются в течение минуты, вернуть их почти невозможно."},
   {"text": "Открыть приложение Авито и проверить, есть ли заказ", "verdict": "safe", "outcome": "В приложении никакого заказа нет — значит, доставку никто не оформлял. Вы ничего не потеряли и можете пожаловаться на собеседника."},
   {"text": "Уточнить у покупателя, официальная ли ссылка", "verdict": "risky", "outcome": "Мошенник уверенно подтвердит, что ссылка официальная, и добавит аргументов. Вы потратите время и с большей вероятностью согласитесь: спрашивать надо не собеседника, а платформу."},
   {"text": "Отправить ему номер карты, чтобы перевёл напрямую", "verdict": "risky", "outcome": "Номер карты сам по себе безопасен для зачисления, но вы остаётесь один на один с мошенником вне защиты сделки — следующим шагом он попросит код из СМС."}
 ]'::jsonb,
 1,
 'Авито никогда не присылает ссылки для получения денег: выплата приходит на привязанную карту автоматически. Любой статус заказа проверяется только внутри приложения — это единственный источник правды. Если действие предлагают совершить на стороннем сайте, это почти всегда фишинг.',
 '["Ссылка на посторонний домен", "Оплата якобы уже зарезервирована", "Действие нужно совершить вне платформы"]'::jsonb),

('seller', 2,
 'Код из СМС',
 'Покупатель договорился о доставке и пишет: «Сервис прислал вам код подтверждения на телефон. Продиктуйте его, без этого я не смогу закрыть заказ». В этот момент вам действительно приходит СМС с шестизначным кодом.',
 'Как поступите?',
 '[
   {"text": "Продиктовать код — иначе сделка сорвётся", "verdict": "dangerous", "outcome": "Код подтверждал вход в ваш аккаунт с чужого устройства. Через минуту вы теряете доступ к профилю, а от вашего имени начинают обманывать других пользователей."},
   {"text": "Не сообщать код и прекратить общение", "verdict": "safe", "outcome": "Заказ, который существует только на словах, отменять нечего. Аккаунт остаётся у вас, а собеседник отправляется в жалобу."},
   {"text": "Продиктовать первые три цифры", "verdict": "dangerous", "outcome": "Мошенник получает половину кода и подбирает остаток либо просто запрашивает новый код, ссылаясь на ошибку. Частичная выдача секрета — это выдача секрета."},
   {"text": "Прислать скриншот СМС", "verdict": "dangerous", "outcome": "На скриншоте виден весь код целиком. Результат тот же, что и при полной диктовке, только быстрее."}
 ]'::jsonb,
 1,
 'Код из СМС приходит на ваш номер и подтверждает действия с вашим аккаунтом: вход, смену пароля, перевод. Настоящему покупателю он не нужен ни в каком виде и ни в какой части. Само появление просьбы назвать код — достаточное основание прервать разговор.',
 '["Просьба назвать одноразовый код", "Ссылка на несуществующие требования сервиса", "Давление срывом сделки"]'::jsonb),

('seller', 3,
 'Скриншот вместо денег',
 'Покупатель прислал скриншот банковского перевода на 45 000 ₽ и пишет: «Оплатил, деньги в пути. Курьер уже у подъезда, отдавайте телефон, я опаздываю». В своём банковском приложении вы никакого поступления не видите.',
 'Ваши действия?',
 '[
   {"text": "Отдать товар — скриншот подтверждает оплату", "verdict": "dangerous", "outcome": "Скриншот был нарисован в графическом редакторе за пару минут. Телефон уезжает с курьером, деньги не приходят никогда."},
   {"text": "Отдать, но взять с курьера расписку", "verdict": "risky", "outcome": "Курьер — обычный исполнитель заказа и за оплату не отвечает. Расписка ни к чему не обязывает отправителя, а товар вы уже отдали."},
   {"text": "Дождаться реального зачисления на счёт", "verdict": "safe", "outcome": "Вы спокойно ждёте. Деньги не приходят, товар остаётся у вас, а покупатель, который на самом деле платил, просто подождал бы пару минут вместе с вами."},
   {"text": "Отдать после звонка в банк отправителя", "verdict": "risky", "outcome": "Банк не станет обсуждать чужие переводы, а вы потеряете время и под нажимом скорее всего всё равно отдадите товар."}
 ]'::jsonb,
 2,
 'Единственное подтверждение оплаты — деньги, которые вы видите в своём банковском приложении. Скриншоты, письма и уведомления подделываются тривиально. Искусственная спешка здесь не случайна: она нужна ровно для того, чтобы вы не успели проверить счёт.',
 '["Подтверждение оплаты картинкой", "Курьер уже на месте", "Давление временем"]'::jsonb),

('seller', 4,
 'Данные карты для бухгалтерии',
 'Покупатель представляется сотрудником компании: «Оформляем покупку на юрлицо. Для перевода бухгалтерии нужны номер карты, срок действия и трёхзначный код с обратной стороны».',
 'Что отправите?',
 '[
   {"text": "Все данные, включая код с обратной стороны", "verdict": "dangerous", "outcome": "Связка номер плюс срок плюс CVC достаточна для оплаты покупок в интернете. Ваша карта начинает расплачиваться за чужие заказы."},
   {"text": "Номер карты и CVC, без срока", "verdict": "dangerous", "outcome": "Срок действия подбирается за несколько попыток. Вы отдали ровно то, что нужно для списания."},
   {"text": "Только номер карты", "verdict": "risky", "outcome": "Для зачисления этого действительно достаточно, и деньги вы не потеряете. Но разговор продолжится, и следующей просьбой будет код из СМС."},
   {"text": "Отказаться и предложить оформить через Авито Доставку", "verdict": "safe", "outcome": "Реальная компания спокойно оплачивает через сервис площадки. Мошенник же откажется — и этим выдаст себя."}
 ]'::jsonb,
 3,
 'Для зачисления денег нужен только номер карты. Срок действия и CVC требуются исключительно для списания — просьба их назвать означает, что у вас хотят не заплатить, а забрать. Статус «компании» проверить в чате невозможно, поэтому он ничего не меняет.',
 '["Запрос CVC", "Легенда о юрлице и бухгалтерии", "Отказ от штатного способа оплаты"]'::jsonb),

('seller', 5,
 'Переплата с возвратом',
 'Покупатель пишет: «Я по ошибке отправил 60 000 вместо 45 000. Верните, пожалуйста, разницу — 15 000 — вот на эту карту, она оформлена на жену». В приложении банка вы действительно видите поступление 60 000 ₽.',
 'Как поступите?',
 '[
   {"text": "Вернуть 15 000 на указанную карту", "verdict": "dangerous", "outcome": "Исходный перевод был сделан с украденной карты и через несколько дней отзывается банком. С вашего счёта списывают все 60 000, а возвращённые 15 000 уходят навсегда — вы в минусе."},
   {"text": "Вернуть разницу только после подтверждения от банка, что платёж окончательный", "verdict": "safe", "outcome": "Банк подтверждает или не подтверждает окончательность операции. Если перевод краденый, он отзывается до того, как вы отдали свои деньги."},
   {"text": "Оставить лишнее себе", "verdict": "risky", "outcome": "Деньги всё равно будут отозваны, а удержание чужого перевода добавит вам разбирательств. Выгоды здесь нет."},
   {"text": "Вернуть всю сумму целиком и отменить сделку", "verdict": "risky", "outcome": "Вы возвращаете 60 000 своими деньгами, а исходный перевод затем отзывается. Потеря — полная сумма."}
 ]'::jsonb,
 1,
 'Возвратное мошенничество строится на разрыве во времени: зачисление видно сразу, а отзыв краденого платежа происходит через дни. Всё, что вы вернули своими деньгами, теряется. Просьба вернуть разницу на другие реквизиты — обязательный признак схемы.',
 '["Перевод больше цены", "Возврат на посторонние реквизиты", "Спешка с возвратом"]'::jsonb),

('seller', 6,
 'Звонок из службы безопасности',
 'Вам звонят с номера, похожего на телефон поддержки: «Служба безопасности Авито. По вашему объявлению зафиксирована подозрительная активность, аккаунт будет заблокирован. Для отмены блокировки назовите код, который сейчас придёт в СМС».',
 'Что сделаете?',
 '[
   {"text": "Назвать код, чтобы не потерять аккаунт", "verdict": "dangerous", "outcome": "Никакой блокировки не было. Код подтверждал вход злоумышленника, и аккаунт вы теряете именно из-за звонка."},
   {"text": "Положить трубку и проверить аккаунт в приложении", "verdict": "safe", "outcome": "Профиль в полном порядке, объявление на месте. Вы убедились, что звонок был поддельным, ничего не отдав."},
   {"text": "Назвать код, а потом сразу сменить пароль", "verdict": "dangerous", "outcome": "К моменту смены пароля злоумышленник уже внутри и первым делом меняет привязанную почту. Восстановить доступ вы не успеваете."},
   {"text": "Перезвонить на тот же номер и уточнить", "verdict": "risky", "outcome": "Обратный звонок попадает тому же человеку: номер в определителе подделан. Проверять нужно в приложении, а не по телефону из звонка."}
 ]'::jsonb,
 1,
 'Поддержка Авито работает только в чате приложения и никогда не звонит с просьбой назвать код. Номер в определителе подделывается бесплатно, поэтому «официальность» звонка ничем не подтверждается. Правильная реакция на любой такой звонок одна: положить трубку и проверить всё самостоятельно.',
 '["Звонок от имени площадки", "Угроза блокировки", "Запрос кода из СМС"]'::jsonb);

INSERT INTO scenarios (role, order_index, title, situation, question, options, correct_option, explanation, red_flags) VALUES
('buyer', 1,
 'Бронь по предоплате',
 'Вы нашли ноутбук за 35 000 ₽ — примерно на 40% дешевле, чем такие же модели у других продавцов. Продавец пишет: «Желающих очень много, но я готов придержать его за вами. Скиньте 3 000 предоплаты, и он ваш».',
 'Ваши действия?',
 '[
   {"text": "Внести предоплату, чтобы не упустить", "verdict": "dangerous", "outcome": "После перевода продавец перестаёт отвечать, а объявление исчезает. Три тысячи вернуть не через что: перевод физлицу добровольный и не оспаривается."},
   {"text": "Внести половину как компромисс", "verdict": "dangerous", "outcome": "Мошеннику безразличен размер суммы — он исчезает и с полутора тысячами. Торг о размере предоплаты не делает её безопасной."},
   {"text": "Отказаться от предоплаты и предложить осмотр или Авито Доставку", "verdict": "safe", "outcome": "Честный продавец соглашается: ему нужна продажа, а не аванс. Мошенник начинает уговаривать или пропадает — и вы узнаёте правду бесплатно."},
   {"text": "Попросить его прислать видео товара и потом внести предоплату", "verdict": "risky", "outcome": "Видео скачивается из чужого объявления за минуту. Вы получаете ложное чувство проверки и всё равно теряете предоплату."}
 ]'::jsonb,
 2,
 'Заниженная цена и искусственный дефицит — это приманка и давление, работающие в паре. Предоплата ничем не защищена: перевод обычному человеку нельзя оспорить, в отличие от сделки через сервис площадки. Платить стоит либо при получении, либо через Авито Доставку, где деньги удерживаются до подтверждения.',
 '["Цена заметно ниже рынка", "Искусственная очередь из желающих", "Требование предоплаты"]'::jsonb),

('buyer', 2,
 'Мимо безопасной сделки',
 'Товар в другом городе. Продавец предлагает: «Авито Доставка удерживает деньги две недели, мне это неудобно. Переведите на карту — отправлю завтра же транспортной компанией, трек-номер пришлю».',
 'Как поступите?',
 '[
   {"text": "Перевести на карту — иначе продаст другому", "verdict": "dangerous", "outcome": "Трек-номер приходит либо поддельный, либо от посылки с кирпичом в другой город. Деньги ушли переводом физлицу и не возвращаются."},
   {"text": "Настоять на оформлении через Авито Доставку", "verdict": "safe", "outcome": "Сервис удерживает деньги до того, как вы получите и проверите товар. Добросовестный продавец на это идёт, мошенник отказывается."},
   {"text": "Перевести половину сейчас, половину после получения", "verdict": "dangerous", "outcome": "Половина суммы теряется ровно так же, как целая. Дробление платежа защищает не вас, а спокойствие мошенника."},
   {"text": "Перевести после того, как он пришлёт фото паспорта", "verdict": "risky", "outcome": "Фото паспорта в чате — чужое, купленное или отредактированное. Оно создаёт видимость гарантии, но не даёт никакой."}
 ]'::jsonb,
 1,
 'Авито Доставка существует именно для сделок между городами: деньги удерживаются сервисом и уходят продавцу только после получения товара. Настойчивый отказ от неё в пользу прямого перевода — главный признак обмана, и никакие объяснения про неудобство его не отменяют.',
 '["Отказ от защищённой сделки", "Перевод напрямую на карту", "Обещание отправить позже"]'::jsonb),

('buyer', 3,
 'Страница, похожая на настоящую',
 'Продавец прислал ссылку «для оплаты через Авито». Страница выглядит в точности как настоящая: тот же логотип, тот же шрифт. В адресной строке: https://avito.ru.secure-pay.example/order. Форма просит номер карты, срок, CVC и код из СМС.',
 'Что сделаете?',
 '[
   {"text": "Ввести данные — страница выглядит официально", "verdict": "dangerous", "outcome": "Внешний вид скопирован целиком. Введённые данные вместе с кодом из СМС дают полный доступ к счёту, и деньги списываются сразу."},
   {"text": "Ввести всё, кроме кода из СМС", "verdict": "dangerous", "outcome": "Номера, срока и CVC достаточно для оплаты во многих магазинах. Код лишь ускорил бы дело, но и без него карта скомпрометирована."},
   {"text": "Закрыть страницу и платить только внутри приложения", "verdict": "safe", "outcome": "Вы уходите с поддельного сайта, ничего не введя. Оплата внутри приложения проходит штатно и защищена сделкой."},
   {"text": "Проверить, что есть замок HTTPS, и тогда ввести", "verdict": "dangerous", "outcome": "Замок означает лишь шифрование канала и есть почти у всех фишинговых сайтов. Он ничего не говорит о честности владельца, и данные уходят мошеннику."}
 ]'::jsonb,
 2,
 'Домен читается справа налево до первого одиночного слэша: здесь владелец адреса — secure-pay.example, а avito.ru лишь часть поддомена для маскировки. Настоящие адреса заканчиваются на avito.ru непосредственно перед слэшем. Внешний вид и наличие HTTPS ничего не подтверждают.',
 '["Домен-двойник", "Запрос CVC и кода из СМС", "Оплата вне приложения"]'::jsonb),

('buyer', 4,
 'Доплата после оплаты',
 'Вы оплатили заказ. Через день продавец пишет: «Посылка застряла на сортировке, служба требует страховку 2 000 ₽. Оплатите, сумму вернут вместе с товаром — иначе отправление уедет обратно».',
 'Ваши действия?',
 '[
   {"text": "Доплатить — сумма небольшая", "verdict": "dangerous", "outcome": "После доплаты появится следующий сбор: за хранение, за таможню, за переоформление. Схема доит жертву, пока та готова платить."},
   {"text": "Доплатить, если пришлют документ от службы доставки", "verdict": "risky", "outcome": "Бланк с печатью рисуется за десять минут. Документ в чате ничего не подтверждает, а вы теряете и эти деньги."},
   {"text": "Не платить и обратиться в поддержку Авито", "verdict": "safe", "outcome": "Поддержка видит реальный статус заказа и отсутствие каких-либо сборов. Деньги за сам заказ защищены сделкой и возвращаются."},
   {"text": "Потребовать вернуть всё и ждать ответа", "verdict": "risky", "outcome": "Требование в чате мошенник просто проигнорирует или продолжит давить. Без обращения в поддержку ситуация не сдвинется."}
 ]'::jsonb,
 2,
 'Требование доплаты после оплаты — приём дожима: человеку, который уже вложился, психологически проще доплатить, чем признать потерю. Реальная доставка не требует ничего сверх суммы заказа, а любые страховки, пошлины и сборы в переписке выдуманы.',
 '["Неожиданный дополнительный платёж", "Обещание вернуть доплату", "Угроза возврата посылки"]'::jsonb),

('buyer', 5,
 'Перевод третьему лицу',
 'Договорились о покупке. Перед оплатой продавец пишет: «У меня карта заблокирована, переведите брату — вот номер телефона, он сразу мне передаст».',
 'Как поступите?',
 '[
   {"text": "Перевести — ситуация бытовая", "verdict": "dangerous", "outcome": "Деньги уходят человеку, который к объявлению отношения не имеет. Доказать банку или площадке, за что был платёж, невозможно."},
